// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface ITrustScore {
    function recordLoan(address _user, uint256 _amount) external;
    function recordRepayment(address _user, uint256 _amount, bool _onTime) external;
    function recordDefault(address _user, uint256 _amount) external;
    function getInterestRate(address _user) external view returns (uint256);
    function calculateTrustScore(address _user) external view returns (uint256);
}

/**
 * @title LendingPool
 * @notice Manages collateralized loans with dynamic interest rates
 * @dev Interest rates are determined by user trust scores
 */
contract LendingPool {
    ITrustScore public trustScore;
    address public owner;
    
    // Loan structure
    struct Loan {
        address borrower;
        uint256 collateralAmount;
        uint256 loanAmount;
        uint256 interestRate; // In basis points (e.g., 1000 = 10%)
        uint256 startTime;
        uint256 duration;
        uint256 dueDate;
        bool active;
        bool repaid;
        bool defaulted;
    }
    
    // State variables
    mapping(uint256 => Loan) public loans;
    mapping(address => uint256[]) public userLoans;
    uint256 public loanCounter;
    uint256 public totalPoolBalance;
    uint256 public constant COLLATERAL_RATIO = 150; // 150% collateralization
    uint256 public constant BASIS_POINTS = 10000;
    
    // Events
    event LoanCreated(
        uint256 indexed loanId,
        address indexed borrower,
        uint256 collateralAmount,
        uint256 loanAmount,
        uint256 interestRate,
        uint256 dueDate
    );
    event LoanRepaid(uint256 indexed loanId, address indexed borrower, uint256 totalAmount);
    event LoanDefaulted(uint256 indexed loanId, address indexed borrower);
    event CollateralWithdrawn(uint256 indexed loanId, address indexed borrower, uint256 amount);
    event PoolDeposit(address indexed depositor, uint256 amount);
    event PoolWithdrawal(address indexed withdrawer, uint256 amount);
    
    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner");
        _;
    }
    
    constructor(address _trustScore) {
        require(_trustScore != address(0), "Invalid trust score address");
        trustScore = ITrustScore(_trustScore);
        owner = msg.sender;
    }
    
    /**
     * @notice Deposit funds to the lending pool
     */
    function depositToPool() external payable {
        require(msg.value > 0, "Must deposit value");
        totalPoolBalance += msg.value;
        emit PoolDeposit(msg.sender, msg.value);
    }
    
    /**
     * @notice Create a new collateralized loan
     * @param _loanAmount Amount to borrow
     * @param _duration Loan duration in seconds
     */
    function createLoan(
        uint256 _loanAmount,
        uint256 _duration
    ) external payable returns (uint256 loanId) {
        require(_loanAmount > 0, "Loan amount must be greater than 0");
        require(_duration > 0, "Duration must be greater than 0");
        require(msg.value > 0, "Must provide collateral");
        
        // Calculate required collateral (150% of loan amount)
        uint256 requiredCollateral = (_loanAmount * COLLATERAL_RATIO) / 100;
        require(msg.value >= requiredCollateral, "Insufficient collateral");
        
        // Check pool has enough funds
        require(totalPoolBalance >= _loanAmount, "Insufficient pool balance");
        
        // Get interest rate from trust score
        uint256 interestRate = trustScore.getInterestRate(msg.sender);
        
        // Create loan
        loanId = loanCounter++;
        uint256 dueDate = block.timestamp + _duration;
        
        loans[loanId] = Loan({
            borrower: msg.sender,
            collateralAmount: msg.value,
            loanAmount: _loanAmount,
            interestRate: interestRate,
            startTime: block.timestamp,
            duration: _duration,
            dueDate: dueDate,
            active: true,
            repaid: false,
            defaulted: false
        });
        
        userLoans[msg.sender].push(loanId);
        
        // Update pool balance
        totalPoolBalance -= _loanAmount;
        
        // Record loan in trust score
        trustScore.recordLoan(msg.sender, _loanAmount);
        
        // Transfer loan amount to borrower
        (bool success, ) = payable(msg.sender).call{value: _loanAmount}("");
        require(success, "Loan transfer failed");
        
        emit LoanCreated(
            loanId,
            msg.sender,
            msg.value,
            _loanAmount,
            interestRate,
            dueDate
        );
        
        return loanId;
    }
    
    /**
     * @notice Repay a loan
     * @param _loanId Loan ID to repay
     */
    function repayLoan(uint256 _loanId) external payable {
        Loan storage loan = loans[_loanId];
        
        require(loan.active, "Loan not active");
        require(loan.borrower == msg.sender, "Not loan borrower");
        require(!loan.repaid, "Loan already repaid");
        require(!loan.defaulted, "Loan defaulted");
        
        // Calculate total repayment amount (principal + interest)
        uint256 totalRepayment = calculateRepaymentAmount(_loanId);
        require(msg.value >= totalRepayment, "Insufficient repayment amount");
        
        // Check if repayment is on time
        bool onTime = block.timestamp <= loan.dueDate;
        
        // Update loan status
        loan.active = false;
        loan.repaid = true;
        
        // Return collateral to borrower
        uint256 collateralToReturn = loan.collateralAmount;
        
        // Add repayment to pool
        totalPoolBalance += totalRepayment;
        
        // Record repayment in trust score
        trustScore.recordRepayment(msg.sender, totalRepayment, onTime);
        
        emit LoanRepaid(_loanId, msg.sender, totalRepayment);
        
        // Return collateral
        (bool success, ) = payable(msg.sender).call{value: collateralToReturn}("");
        require(success, "Collateral return failed");
        
        // Return excess payment if any
        if (msg.value > totalRepayment) {
            uint256 excess = msg.value - totalRepayment;
            (bool excessSuccess, ) = payable(msg.sender).call{value: excess}("");
            require(excessSuccess, "Excess return failed");
        }
    }
    
    /**
     * @notice Liquidate a defaulted loan
     * @param _loanId Loan ID to liquidate
     */
    function liquidateLoan(uint256 _loanId) external {
        Loan storage loan = loans[_loanId];
        
        require(loan.active, "Loan not active");
        require(!loan.repaid, "Loan already repaid");
        require(block.timestamp > loan.dueDate, "Loan not yet due");
        
        // Mark as defaulted
        loan.active = false;
        loan.defaulted = true;
        
        // Add collateral to pool
        totalPoolBalance += loan.collateralAmount;
        
        // Record default in trust score
        trustScore.recordDefault(loan.borrower, loan.loanAmount);
        
        emit LoanDefaulted(_loanId, loan.borrower);
    }
    
    /**
     * @notice Calculate total repayment amount for a loan
     * @param _loanId Loan ID
     * @return totalAmount Total amount to repay (principal + interest)
     */
    function calculateRepaymentAmount(uint256 _loanId) public view returns (uint256 totalAmount) {
        Loan memory loan = loans[_loanId];
        
        // Calculate interest: (principal * rate * duration) / (BASIS_POINTS * 365 days)
        uint256 interest = (loan.loanAmount * loan.interestRate * loan.duration) / 
                          (BASIS_POINTS * 365 days);
        
        totalAmount = loan.loanAmount + interest;
        return totalAmount;
    }
    
    /**
     * @notice Get all loan IDs for a user
     * @param _user User address
     */
    function getUserLoans(address _user) external view returns (uint256[] memory) {
        return userLoans[_user];
    }
    
    /**
     * @notice Owner can withdraw excess pool funds
     * @param _amount Amount to withdraw
     */
    function withdrawPoolFunds(uint256 _amount) external onlyOwner {
        require(_amount <= totalPoolBalance, "Insufficient pool balance");
        totalPoolBalance -= _amount;
        
        emit PoolWithdrawal(msg.sender, _amount);
        
        (bool success, ) = payable(owner).call{value: _amount}("");
        require(success, "Withdrawal failed");
    }
    
    /**
     * @notice Get pool statistics
     */
    function getPoolStats() external view returns (
        uint256 balance,
        uint256 totalLoans,
        uint256 activeLoans
    ) {
        uint256 active = 0;
        for (uint256 i = 0; i < loanCounter; i++) {
            if (loans[i].active) {
                active++;
            }
        }
        
        return (totalPoolBalance, loanCounter, active);
    }
}

contracts/TrustScore.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title TrustScore
 * @notice Calculates and manages user trust scores based on on-chain behavior
 * @dev Trust scores range from 0-100 and affect lending interest rates
 */
contract TrustScore {
    // User trust data
    struct UserData {
        uint256 totalLoans;
        uint256 successfulRepayments;
        uint256 latePayments;
        uint256 defaultedLoans;
        uint256 totalBorrowed;
        uint256 totalRepaid;
        uint256 accountAge;
        bool exists;
    }
    
    mapping(address => UserData) public userData;
    address public lendingPool;
    address public owner;
    
    // Events
    event TrustScoreUpdated(address indexed user, uint256 newScore);
    event LoanRecorded(address indexed user, uint256 amount);
    event RepaymentRecorded(address indexed user, uint256 amount, bool onTime);
    event DefaultRecorded(address indexed user, uint256 amount);
    
    modifier onlyLendingPool() {
        require(msg.sender == lendingPool, "Only lending pool");
        _;
    }
    
    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner");
        _;
    }
    
    constructor() {
        owner = msg.sender;
    }
    
    /**
     * @notice Set the lending pool address
     * @param _lendingPool Address of the lending pool contract
     */
    function setLendingPool(address _lendingPool) external onlyOwner {
        require(_lendingPool != address(0), "Invalid address");
        lendingPool = _lendingPool;
    }
    
    /**
     * @notice Record a new loan
     * @param _user Borrower address
     * @param _amount Loan amount
     */
    function recordLoan(address _user, uint256 _amount) external onlyLendingPool {
        UserData storage data = userData[_user];
        
        if (!data.exists) {
            data.exists = true;
            data.accountAge = block.timestamp;
        }
        
        data.totalLoans++;
        data.totalBorrowed += _amount;
        
        emit LoanRecorded(_user, _amount);
        emit TrustScoreUpdated(_user, calculateTrustScore(_user));
    }
    
    /**
     * @notice Record a loan repayment
     * @param _user Borrower address
     * @param _amount Repayment amount
     * @param _onTime Whether repayment was on time
     */
    function recordRepayment(
        address _user,
        uint256 _amount,
        bool _onTime
    ) external onlyLendingPool {
        UserData storage data = userData[_user];
        require(data.exists, "User not found");
        
        data.totalRepaid += _amount;
        
        if (_onTime) {
            data.successfulRepayments++;
        } else {
            data.latePayments++;
        }
        
        emit RepaymentRecorded(_user, _amount, _onTime);
        emit TrustScoreUpdated(_user, calculateTrustScore(_user));
    }
    
    /**
     * @notice Record a loan default
     * @param _user Borrower address
     * @param _amount Defaulted amount
     */
    function recordDefault(address _user, uint256 _amount) external onlyLendingPool {
        UserData storage data = userData[_user];
        require(data.exists, "User not found");
        
        data.defaultedLoans++;
        
        emit DefaultRecorded(_user, _amount);
        emit TrustScoreUpdated(_user, calculateTrustScore(_user));
    }
    
    /**
     * @notice Calculate trust score for a user (0-100)
     * @param _user User address
     * @return score Trust score
     */
    function calculateTrustScore(address _user) public view returns (uint256 score) {
        UserData memory data = userData[_user];
        
        if (!data.exists || data.totalLoans == 0) {
            return 0;
        }
        
        // Base score from repayment history (0-60 points)
        uint256 repaymentScore = 0;
        if (data.totalLoans > 0) {
            repaymentScore = (data.successfulRepayments * 60) / data.totalLoans;
        }
        
        // Account age bonus (0-20 points)
        uint256 ageInDays = (block.timestamp - data.accountAge) / 1 days;
        uint256 ageScore = ageInDays > 365 ? 20 : (ageInDays * 20) / 365;
        
        // Activity score (0-20 points)
        uint256 activityScore = data.totalLoans > 10 ? 20 : (data.totalLoans * 20) / 10;
        
        // Calculate base score
        score = repaymentScore + ageScore + activityScore;
        
        // Apply penalties
        uint256 latePenalty = data.latePayments * 5;
        uint256 defaultPenalty = data.defaultedLoans * 15;
        uint256 totalPenalty = latePenalty + defaultPenalty;
        
        // Ensure score doesn't go below 0
        if (totalPenalty >= score) {
            score = 0;
        } else {
            score -= totalPenalty;
        }
        
        // Cap at 100
        if (score > 100) {
            score = 100;
        }
        
        return score;
    }
    
    /**
     * @notice Get interest rate based on trust score
     * @param _user User address
     * @return rate Interest rate in basis points (e.g., 1000 = 10%)
     */
    function getInterestRate(address _user) external view returns (uint256 rate) {
        uint256 trustScore = calculateTrustScore(_user);
        
        // Interest rate formula: 30% - (trustScore * 0.2%)
        // High trust (100) = 10% APR
        // Medium trust (50) = 20% APR
        // Low trust (0) = 30% APR
        
        uint256 baseRate = 3000; // 30% in basis points
        uint256 discount = (trustScore * 20); // 0.2% per trust point
        
        if (discount >= baseRate) {
            rate = 1000; // Minimum 10%
        } else {
            rate = baseRate - discount;
        }
        
        return rate;
    }
}

